18: import { HttpClient, HttpErrorResponse } from '@angular/common/http';
19: import { inject, Injectable } from '@angular/core';
20: import { NGXLogger } from 'ngx-logger';
21: import { Observable, throwError } from 'rxjs';
22: import { catchError, map } from 'rxjs/operators';
23: import { ConfigService } from 'src/app/config.service';
24: import { IgsMeldung } from '../../app/components/igs-meldung/igs-meldung.types';
25: 
26: export type MeldungSubmitResponse = {
27:   meldungId?: string;
28:   laborId?: string;
29:   igsId?: string;
30: };
31: 
32: export type MeldungSubmitResponseError = {
33:   detail: string;
34:   instance: string;
35:   status: number;
36:   timestamp: string;
37:   title: string;
38:   type: string;
39: };
40: 
41: export type MeldungSubmitParams = { metadata: IgsMeldung.OverviewData };
42: 
43: @Injectable({
44:   providedIn: 'root',
45: })
46: export class MeldungSubmitService {
47:   private readonly configService = inject(ConfigService);
48:   private readonly http = inject(HttpClient);
49:   private readonly logger = inject(NGXLogger);
50: 
51:   submitMeldung({ metadata }: MeldungSubmitParams): Observable<MeldungSubmitResponse> {
52:     this.logger.debug('submitMeldung for demisNotificationId: ', metadata.demisNotificationId);
53:     return this.http.post<any>(`${this.configService.igsGatewayUrl}/notification-sequence/$process-notification-sequence`, metadata).pipe(
54:       map(response => {
55:         this.logger.debug('submitMeldung response', response);
56:         const result: MeldungSubmitResponse = {};
57: 
58:         response?.parameter?.forEach((param: any) => {
59:           if (param.name === 'transactionID') {
60:             result.igsId = param.valueIdentifier.value;
61:           } else if (param.name === 'submitterGeneratedNotificationID') {
62:             result.meldungId = param.valueIdentifier.value;
63:           } else if (param.name === 'labSequenceID') {
64:             result.laborId = param.valueIdentifier.value;
65:           }
66:         });
67: 
68:         return result;
69:       }),
70:       catchError((error: HttpErrorResponse) => {
71:         this.logger.error('submitMeldung failed', error);
72:         return throwError(() => error);
73:       })
74:     );
75:   }
76: }

